255	export async function listCustomerBookings(
256	  customerId: string,
257	): Promise<BookingRow[]> {
258	  const supabase = await createClient();
259	  const { data, error } = await supabase
260	    .from("bookings")
261	    .select("*")
262	    .eq("customer_id", customerId)
263	    .order("created_at", { ascending: false });
264	  if (error) throw error;
265	  return data ?? [];
266	}
267	
268	/** Bookings made with the signed-in provider, newest first. */
269	export async function listProviderBookings(
270	  providerId: string,
271	): Promise<BookingRow[]> {
272	  const supabase = await createClient();
273	  const { data, error } = await supabase
274	    .from("bookings")
275	    .select("*")
276	    .eq("provider_id", providerId)
277	    .order("created_at", { ascending: false });
278	  if (error) throw error;
279	  return data ?? [];
280	}
281	
282	/** A single booking the caller is party to, or null. */
283	export async function getBooking(id: string): Promise<BookingRow | null> {
284	  const supabase = await createClient();
285	  const { data, error } = await supabase
286	    .from("bookings")
287	    .select("*")
288	    .eq("id", id)
289	    .maybeSingle();
